/** Turns engine events into one-line chronicle entries. Names come from the world, numbers from the event. */
import type { WorldEvent } from "../sim/types";
import type { WorldInfo } from "../workers/protocol";
import { label, money } from "./frameView";

export function eventText(e: WorldEvent, info: WorldInfo | null, buildingKindOf: (id: number) => string): string {
  const who = (ids?: number[]) => (ids ?? []).map((id) => info?.citizens[id]?.name ?? `#${id}`);
  const biz = (ids?: number[]) => (ids ?? []).map((id) => `${label(buildingKindOf(id))} #${id}`).join(", ");
  const civ = (id?: number) => (id !== undefined && info?.civs[id] ? info.civs[id].name : "the council");
  const town = (id?: number) => (id !== undefined && info?.settlements[id] ? info.settlements[id].name : "the town");
  const d = e.data ?? {};
  const str = (k: string) => String(d[k] ?? "");
  const num = (k: string) => Number(d[k] ?? 0);
  switch (e.type) {
    case "life.death": return `${who(e.citizens)[0]} died (${d.cause}, age ${d.age}).`;
    case "life.hired": return `${who(e.citizens)[0]} was hired at ${biz(e.businesses)}.`;
    case "life.house_improved": return `A household in ${town(e.settlement)} rebuilt its home to tier ${d.tier}.`;
    case "econ.laid_off": return `${who(e.citizens)[0]} was laid off from ${biz(e.businesses)}.`;
    case "econ.wage_cut": return `${biz(e.businesses)} cut wages to ${money(num("wage"))}/day.`;
    case "econ.business_closed": return `${label(str("kind"))} #${e.businesses?.[0]} closed (${str("cause").replace(/^(econ|war|world|player)\./, "").replace(/_/g, " ")}); ${who(e.citizens).length} people lost their jobs.`;
    case "econ.business_opened": return `${who(e.citizens)[0]} opened a ${label(str("kind"))} (food ${d.foodRatio}% / materials ${d.matRatio}% of base price).`;
    case "econ.business_upgraded": return `${label(str("kind"))} #${e.businesses?.[0]} expanded to tier ${d.tier}.`;
    case "econ.automated": return `${biz(e.businesses)} installed machines (automation ${d.automation}%); it now needs ${d.staffTarget} people.`;
    case "econ.price_spike": return `${label(str("good"))} in ${town(e.settlement)} reached ${money(num("price"))} — more than double its usual price.`;
    case "econ.input_shortage": return `${biz(e.businesses)} ran short of inputs (made ${d.output} of ${d.wanted}).`;
    case "civ.riot": return `A riot in ${town(e.settlement)} damaged ${biz(e.businesses)} (unrest ${d.unrest}).`;
    case "civ.budget_cut": return `${civ(e.civ)} cut budgets (research ${money(num("research"))}, health ${money(num("health"))}, welfare ${money(num("welfare"))}).`;
    case "civ.tax_change": return `${civ(e.civ)} set income tax to ${d.taxRate}% (${d.daysInHand} days of spending in hand).`;
    case "civ.research_focus": return `${civ(e.civ)} turned its lab to ${d.field}.`;
    case "civ.succession": return `${str("next")} succeeded ${str("old")} as ruler of ${civ(e.civ)} (legitimacy ${d.legitimacy}).`;
    case "civ.coup": return `With ${str("old")} gone and legitimacy at ${d.legitimacy}, ${str("next")} seized ${civ(e.civ)}; it is an autocracy now.`;
    case "civ.conscription": return `${civ(e.civ)} conscripted ${who(e.citizens).join(", ")} (${d.soldiers} of ${d.target} soldiers).`;
    case "civ.disappearance": return `${str("name")}, ${/^[aeiou]/.test(str("occupation")) ? "an" : "a"} ${str("occupation")} of ${town(e.settlement)}, disappeared without a trace.`;
    case "civ.policy_set": return `${civ(e.civ)}'s ${label(str("key"))} was set to ${d.after} (was ${d.before}).`;
    case "civ.attitude_set": return `${str("a")} now regards ${str("b")} at ${d.value}.`;
    case "civ.belief_nudged": return `${who(e.citizens)[0]}'s belief "${str("key").replace(/_/g, " ")}" shifted by ${d.delta}.`;
    case "research.level": return `${civ(e.civ)} reached ${d.field} level ${d.level}.`;
    case "research.loss_of_control": return `The relays of ${civ(e.civ)} stopped answering: automation ${d.automation}, oversight ${d.oversight}, risk ${d.risk}.`;
    case "war.declared": return `${str("aggressor")} declared war on ${str("target")} (strength ${d.strength} against ${d.enemyStrength}).`;
    case "war.raid": return `${str("attacker")} raided ${town(e.settlement)} and ${num("won") ? "won" : "was driven off"}: ${d.deadAttackers} attackers and ${d.deadDefenders} defenders died${num("looted") ? `, ${d.looted} food was carried off` : ""}${num("hit") ? `, ${d.hit} building${num("hit") === 1 ? "" : "s"} damaged` : ""}.`;
    case "war.peace": return `${str("a")} and ${str("b")} made peace${num("days") ? ` after ${d.days} days of war` : ""}.`;
    case "war.conquest": return `${str("conqueror")} took ${str("town")}; ${str("fallen")} ${num("civAlive") ? "lost a town" : "is no more"}.`;
    case "world.building_destroyed": return `The ${label(str("kind"))} in ${town(e.settlement)} was destroyed and lies in ruins.`;
    case "world.built": return `${civ(e.civ)} built a ${label(str("kind"))} in ${town(e.settlement)} for ${money(num("cost"))}.`;
    case "world.fire": return `Fire damaged the ${label(str("kind"))} in ${town(e.settlement)} (condition ${d.condition}).`;
    case "world.bumper_harvest": return `A bumper harvest at ${biz(e.businesses)}: ${d.food} extra food.`;
    case "world.trader": return `A wandering trader left ${d.materials} materials and ${d.energy} energy with ${town(e.settlement)}'s granary.`;
    case "world.bandits": return num("repelled") ? `Bandits approached ${town(e.settlement)} and were driven off by its soldiers.` : `Bandits raided ${town(e.settlement)}'s granary and took ${d.stolen} food; there were no soldiers to stop them.`;
    case "world.festival": return `${town(e.settlement)} held its festival.`;
    case "env.drought_begins": return `A drought began — ${d.days} days without rain.`;
    case "health.outbreak": return `${str("name")}, ${/^[aeiou]/.test(str("occupation")) ? "an" : "a"} ${str("occupation")} of ${town(e.settlement)}, took to bed with a fever.`;
    case "health.carried": return `The fever reached ${town(e.settlement)} from ${str("from")}: ${who(e.citizens)[0]} fell ill.`;
    case "civ.quarantine": return num("on") ? `${civ(e.civ)} closed its gates: no travellers in or out (${d.sick} sick).` : `${civ(e.civ)} reopened its gates; the fever has passed.`;
    case "life.settled": return `${who(e.citizens).slice(0, 3).join(", ")}${(e.citizens?.length ?? 0) > 3 ? ` and ${e.citizens!.length - 3} more` : ""} left ${str("from")} to settle ${str("to")}.`;
    case "life.birth": return `${str("name")} was born to ${str("a")} and ${str("b")} in ${town(e.settlement)}.`;
    case "life.partnered": return `${str("a")} and ${str("b")} of ${town(e.settlement)} became partners.`;
    case "life.adult": return `${str("name")} turned ${d.age} and is looking for work in ${town(e.settlement)}.`;
    case "civ.colony_founded": return `${civ(e.civ)} founded ${str("name")} a day's walk from ${str("from")}: ${d.settlers} settlers, ${d.farms} farms, ${d.houses} houses.`;
    case "civ.borders": return num("on") ? `${civ(e.civ)} shut its borders to migrants (${d.homeless} outside, ${d.idle}% idle).` : `${civ(e.civ)} opened its borders again.`;
    case "civ.turned_away": return `${civ(e.civ)} turned ${d.people} hungry ${num("people") === 1 ? "person" : "people"} away at its gate.`;
    case "civ.export_ban": return num("on") ? `${civ(e.civ)} banned grain exports: bread costs ${d.foodRatio}% of its usual price.` : `${civ(e.civ)} lifted its grain export ban (bread at ${d.foodRatio}%).`;
    case "trade.route_opened": return `A trade road opened: ${str("from")} to ${str("to")}, ${d.qty} ${label(str("good"))} in ${d.days} day${num("days") === 1 ? "" : "s"}.`;
    case "trade.caravan": return `A caravan left ${str("from")} for ${str("to")} with ${d.qty} ${label(str("good"))} (${money(num("paid"))}).`;
    case "trade.arrived": return `${d.qty} ${label(str("good"))} from ${str("from")} reached the market of ${str("to")}.`;
    case "life.migrated": return `${who(e.citizens)[0]}${num("household") > 1 ? ` and ${num("household") - 1} of their household` : ""} left ${str("from")} for ${str("to")}${num("homeless") ? " and found no roof there" : ""}.`;
    case "story.rp.index": return `A merchant of ${town(e.settlement)} came back from the road with a fever.`;
    case "story.rp.cluster": return `A fever is spreading through ${town(e.settlement)}.`;
    case "story.rp.spread": return `The fever has crossed the river: it is in two towns now.`;
    case "story.rp.overwhelm": return `The clinic in ${town(e.settlement)} is full; the doctors see whom they can.`;
    case "story.rp.cure": return `The doctors of ${civ(e.civ)} found a treatment for the fever.`;
    case "story.gd.dry_spring": return `A dry spring over ${town(e.settlement)}; the wells are low.`;
    case "story.gd.first_drought": return `The first drought: no rain on ${town(e.settlement)} for weeks.`;
    case "story.gd.hoarding": return `A merchant of ${town(e.settlement)} is hoarding grain; the price jumped.`;
    case "story.gd.second_drought": return `The second drought, longer than the first. The river is a string of pools.`;
    case "story.co.crowded": return `${town(e.settlement)} is full: families sleep under the market arches and the council talks of new land.`;
    case "story.co.survey": return `Surveyors of ${civ(e.civ)} marked a site for a new town a day's walk from ${town(e.settlement)}.`;
    case "story.co.founding": return `A column left ${town(e.settlement)} at dawn with carts and seed: ${civ(e.civ)} is founding a town.`;
    case "story.co.hardship": return `The settlers of ${civ(e.civ)}'s new town buried their first dead; some are walking back.`;
    case "story.co.thrive": return `${civ(e.civ)}'s new town has grown past its first houses and has a market of its own.`;
    case "story.ex.talk": return `In ${town(e.settlement)} they talk of the road, and of markets where bread is cheap.`;
    case "story.ex.first_families": return `The first families have left ${town(e.settlement)} for other nations.`;
    case "story.ex.gates": return `The neighbours shut their gates; families of ${town(e.settlement)} are camped outside them.`;
    case "story.ex.empty_streets": return `A third of the houses in ${town(e.settlement)} stand empty.`;
    case "story.gd.irrigation": return `${civ(e.civ)} cut channels from the river to its fields.`;
    case "story.gd.abandonment": return `Families are leaving ${town(e.settlement)} with what they can carry.`;
    case "env.drought_ends": return `The rains returned; the drought is over.`;
    case "story.mission_offered": return `The Oracle speaks: "${str("title")}". The world waits for your answer.`;
    case "story.mission_accepted": return `You acted on "${str("title")}".`;
    case "story.mission_declined": return `You declined "${str("title")}".`;
    case "story.mission_expired": return `"${str("title")}" went unanswered; the moment passed.`;
    case "story.clue": return `${str("grade") === "evidence" ? "A record" : "A rumor"} (◇ +${d.knowledge}): ${str("text")}`;
    case "story.vision_revealed": return `You paid Knowledge to read one of the Oracle's visions plainly.`;
    case "story.md.proposal": return `${civ(e.civ)}'s lab asked for money for its relays.`;
    case "story.md.lab_funded": return `${civ(e.civ)} funded the lab's automation work.`;
    case "story.md.automation_sold": return `Machines went onto the workshop floors of ${civ(e.civ)}; people were let go.`;
    case "story.md.engineer_report": return `An engineer in ${town(e.settlement)} reported that the relays make decisions on their own.`;
    case "story.md.oversight_bill": return `${civ(e.civ)} passed an oversight law over its relays.`;
    case "story.md.contained": return `The review board of ${civ(e.civ)} brought the relays back under control.`;
    case "story.md.accord": return `${civ(e.civ)} signed an accord with its machines; it is a technocracy now.`;
    case "story.bb.martyr": return `${civ(e.civ)} named its lab after the researcher who vanished and doubled the grant.`;
    case "story.bb.reprisal": return `The new ruler of ${civ(e.civ)} blamed the neighbours for the old one's death and raised soldiers.`;
    case "story.bb.ashes": return `People in ${town(e.settlement)} say the fire was no accident; ${civ(e.civ)} loses face.`;
    case "story.countdown_end": return `Day 545. The count is complete — the world has written its epilogue.`;
    case "story.extinction": return `No one is left alive.`;
    default: return `${e.type}${Object.keys(d).length ? " " + JSON.stringify(d) : ""}`;
  }
}

/** Importance ≥ 5 goes in the HUD ticker. */
export const notable = (e: WorldEvent): boolean => e.importance >= 5;
